import { createContext, useContext, useState } from "react";

// Create context for the cart
const CartContext = createContext();

export const CartProvider = ({ children }) => {
    // State for the cart and orders
    const [cart, setCart] = useState([]);
    const [orders, setOrders] = useState([]);

    // Add product to cart
    const addToCart = (product) => {
        setCart((prevCart) => [...prevCart, product]);
    };

    // Remove product from cart by ID
    const removeFromCart = (id) => {
        setCart((prevCart) => prevCart.filter((item) => item.id !== id));
    };

    // Calculate total number of items in the cart
    const totalItems = cart.length;

    // Calculate total price of items in the cart
    const totalPrice = cart.reduce((sum, item) => sum + item.price, 0);

    // Handle checkout and save the order
    const checkout = () => {
        if (cart.length === 0) {
            alert("Giỏ hàng trống!");  // Cart is empty, alert the user
            return;
        }

        // Create a new order
        const newOrder = {
            id: orders.length + 1,
            items: [...cart],
            total: totalPrice,
            date: new Date().toLocaleString()
        };

        // Save the new order to orders state
        setOrders((prevOrders) => [...prevOrders, newOrder]);

        // Empty the cart after the order
        setCart([]);

        // Show success message
        alert("Đơn hàng của bạn đã được đặt thành công!");
    };

    return (
        <CartContext.Provider
            value={{
                cart,
                addToCart,
                removeFromCart,
                totalItems,
                totalPrice,
                checkout,
                orders
            }}
        >
            {children}
        </CartContext.Provider>
    );
};

// Custom hook to use the cart context
export const useCart = () => useContext(CartContext);
